(function(root){
 'use strict';
 const F=root.Football||(typeof require==='function'?require('./engine.js'):null);
 const first=['레온','루카','에밀','노아','테오','다리오','마르코','이든','리오','니코','오스카','루벤','핀','카일','엘리안','레미'];
 const last=['브렌','베일','렌츠','코르빈','할베른','모렐','리드','펠스','카르벤','에버릭','알베크','윌렌','바르덴','로웬','네런','세르반'];
 const layouts={442:{DEF:4,MID:4,FW:2},433:{DEF:4,MID:3,FW:3},352:{DEF:3,MID:5,FW:2}},keys={GK:'keeping',DEF:'defense',MID:'passing',FW:'attack'},labels={GK:'선방',DEF:'수비',MID:'패스',FW:'결정력'};
 const clamp=n=>Math.max(1,Math.min(99,Math.round(n))),mean=a=>a.reduce((n,p)=>n+p,0)/a.length;
 function plan(club){const style=club.style||'',kind=/압박/.test(style)?'press':/역습/.test(style)?'counter':/측면/.test(style)?'wide':/패스|중원/.test(style)?'possession':'balanced';return {formation:kind==='press'||kind==='wide'?'433':kind==='possession'?'352':'442',kind,label:{press:'전방 압박',counter:'수비 후 빠른 역습',wide:'측면 공격',possession:'중원과 패스 중심',balanced:'균형 운영'}[kind],description:style};}
 function roster(club,profile=club,minute=0){
  const p=plan(club),positions=['GK',...Object.entries(layouts[p.formation]).flatMap(([pos,n])=>Array(n).fill(pos))],counts={GK:0,DEF:0,MID:0,FW:0};let hash=0;for(const ch of club.id||club.name)hash=(Math.imul(hash,31)+ch.charCodeAt(0))>>>0;
  return positions.map((pos,i)=>{const index=counts[pos]++,total=pos==='GK'?1:layouts[p.formation][pos],offset=index*2-(total-1),base={id:'opp'+i,identity:'opposition:'+club.id+':'+i,name:first[(hash+i)%first.length]+' '+last[(Math.floor(hash/17)+i*3)%last.length],no:i+1,pos,attack:clamp(pos==='FW'?profile.attack+offset:profile.attack-(pos==='GK'?44:pos==='DEF'?30:10)+offset),defense:clamp(pos==='DEF'?profile.defense+offset:profile.defense-(pos==='GK'?13:pos==='MID'?20:42)+offset),passing:clamp(pos==='MID'?profile.middle+offset:profile.middle-(pos==='GK'?20:12)+offset),speed:clamp(profile.speed+(pos==='FW'?16:pos==='MID'?10:pos==='GK'?-8:0)+offset),keeping:pos==='GK'?profile.defense:0,endurance:50,energy:Math.max(0,(profile.energy??94)-minute*35/90)};return {...base,primary:base[keys[pos]],primaryLabel:labels[pos],condition:base.energy<50?'소진':base.energy<65?'지침':base.energy<80?'보통':'좋음'};});
 }
 function profile(club){const r=roster(club),group=pos=>r.filter(p=>p.pos===pos);return {attack:Math.round(mean(group('FW').map(p=>p.attack))),defense:Math.round(.7*mean(group('DEF').map(p=>p.defense))+.3*group('GK')[0].keeping),middle:Math.round(mean(group('MID').map(p=>p.passing))),speed:Math.round(mean(group('DEF').map(p=>p.speed))),energy:94};}
 function read(s){const S=root.Season||(typeof require==='function'?require('./season.js'):null),m=s?.match,club=m&&S.opponentFor(s);if(!m||!club)return {valid:false};const p=plan(club),lineup=roster(club,m.opponent,m.minute),rating=F.ratings(m),own=m.lineup.map(id=>m.players[id]),rows=S.standings(s),rank=rows.find(r=>r.id===club.id),recent=s.results.filter(r=>r.home===club.id||r.away===club.id).slice(-5).map(r=>{const [a,b]=r.home===club.id?r.goals:[r.goals[1],r.goals[0]];return a>b?'승':a===b?'무':'패';});
  return {valid:true,club:{id:club.id,name:club.name,short:club.short,code:club.code,color:club.color},plan:p,lineup,minute:m.minute,rank:rank?.played?rank.rank:null,points:rank?.points??null,recent,condition:{opponent:lineup[0].energy,ours:mean(own.map(p=>p.energy)),tired:own.filter(p=>p.energy<65).length},comparisons:[['attack','공격',rating.attack],['defense','수비',rating.defense],['middle','중원',rating.middle],['speed','수비 속도',rating.pace]].map(([key,label,ours])=>({key,label,opponent:rating.opponent[key],ours})),advice:m.opponent.speed<60?'상대 수비가 느립니다. 빠른 공격수와 역습을 비교해 보세요.':m.opponent.middle>m.opponent.defense?'중원 패스가 강점입니다. 압박의 체력 소모와 수비 간격을 함께 확인하세요.':'수비 조직이 강점입니다. 공격적인 운영과 빠른 전환을 비교해 보세요.'};
 }
 const api={plan,roster,profile,read};root.Opposition=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
